package com.yeyamo_mobile.api.discovery_service.application.maps;
import org.springframework.stereotype.Service;import com.yeyamo_mobile.api.discovery_service.application.port.ExternalMapsPort;
@Service public class MapsService{private final ExternalMapsPort maps;public MapsService(ExternalMapsPort maps){this.maps=maps;}public GeocodeResult geocode(String address){if(address==null||address.isBlank())throw new IllegalArgumentException("Address is required");return maps.geocode(address.trim());}public GeocodeResult reverse(double latitude,double longitude){return maps.reverseGeocode(new Coordinate(latitude,longitude));}public RouteResult route(Coordinate origin,Coordinate destination,TravelMode mode){if(origin==null||destination==null)throw new IllegalArgumentException("Origin and destination are required");return maps.route(origin,destination,mode==null?TravelMode.DRIVE:mode);}}
